<?php
/** Plugin Name: Brújula Digital — Catálogo de herramientas
 * Description: CPT, taxonomías y campos base para el catálogo editorial de Brújula Digital.
 * Version: 0.1.0
 */
defined('ABSPATH') || exit;
final class Brujula_Digital_Catalog {
    private const TYPE = 'herramientas'; private const NONCE = 'bd_save_tool';
    public static function boot(): void { add_action('init',[self::class,'register_model']); add_action('add_meta_boxes',[self::class,'add_box']); add_action('save_post_'.self::TYPE,[self::class,'save'],10,2); add_filter('post_type_link',[self::class,'landing_link'],10,2); add_shortcode('brujula_herramienta',[self::class,'shortcode']); add_filter('the_content',[self::class,'append_recommendation']); add_action('wp_head',[self::class,'styles']); add_action('wp_footer',[self::class,'conversion_tracking']); }
    public static function register_model(): void { register_post_type(self::TYPE,['labels'=>['name'=>'Herramientas','singular_name'=>'Herramienta','add_new_item'=>'Añadir herramienta','edit_item'=>'Editar herramienta'],'public'=>true,'show_in_rest'=>true,'menu_icon'=>'dashicons-compass','has_archive'=>true,'rewrite'=>['slug'=>'herramientas'],'supports'=>['title','editor','excerpt','thumbnail','revisions']]); foreach(['necesidad'=>'Necesidades','perfil'=>'Perfiles','nivel'=>'Nivel','tipo'=>'Tipos'] as $slug=>$label) register_taxonomy($slug,[self::TYPE],['label'=>$label,'public'=>true,'show_in_rest'=>true,'hierarchical'=>true,'rewrite'=>['slug'=>$slug]]); }
    private static function fields(): array { return ['landing_url'=>'URL de landing de conversión','brand'=>'Marca','one_liner'=>'Frase de utilidad','problem'=>'Problema que resuelve','audience_yes'=>'Para quién sí','audience_no'=>'Para quién no','use_cases'=>'Casos de uso','advantages'=>'Ventajas','limitations'=>'Limitaciones','difficulty'=>'Dificultad','alternatives'=>'Alternativas','price'=>'Precio y fecha de revisión','official_url'=>'URL oficial','affiliate_url'=>'URL afiliada interna','affiliate_status'=>'Estado de afiliación','policy_reviewed'=>'Política revisada el','sources'=>'Fuentes y evidencia','editorial_status'=>'Estado editorial']; }
    public static function add_box(): void { add_meta_box('bd_tool_details','Datos de la herramienta',[self::class,'box'],self::TYPE,'normal','high'); }
    public static function landing_link(string $url, WP_Post $post): string {
        if($post->post_type!==self::TYPE)return $url;
        $landing=(string)get_post_meta($post->ID,'_bd_landing_url',true);
        if(!$landing && $post->post_name==='aihomedesign-home-staging-virtual-para-captar-mejor') {
            $landing=home_url('/aihomedesign-home-staging-virtual-para-presentar-mejor-una-vivienda/');
        }
        return $landing?esc_url_raw($landing):$url;
    }
    public static function box(WP_Post $post): void { wp_nonce_field(self::NONCE,self::NONCE); foreach(self::fields() as $key=>$label){$v=get_post_meta($post->ID,'_bd_'.$key,true);$area=in_array($key,['use_cases','advantages','limitations','sources'],true);echo '<p><label for="bd_'.$key.'"><strong>'.esc_html($label).'</strong></label>'; if($area) echo '<textarea class="widefat" rows="3" id="bd_'.$key.'" name="bd_'.$key.'">'.esc_textarea($v).'</textarea>'; else echo '<input class="widefat" type="text" id="bd_'.$key.'" name="bd_'.$key.'" value="'.esc_attr($v).'">'; echo '</p>';}}
    public static function save(int $id): void { if(!isset($_POST[self::NONCE])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST[self::NONCE])),self::NONCE)|| (defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)||!current_user_can('edit_post',$id)) return; foreach(array_keys(self::fields()) as $key){$raw=isset($_POST['bd_'.$key])?wp_unslash($_POST['bd_'.$key]):'';$v=in_array($key,['use_cases','advantages','limitations','sources'],true)?sanitize_textarea_field($raw):sanitize_text_field($raw);update_post_meta($id,'_bd_'.$key,$v);}}
    public static function shortcode(): string { $id=get_the_ID(); if(!$id||get_post_type($id)!==self::TYPE)return ''; $get=static fn(string $k)=>(string)get_post_meta($id,'_bd_'.$k,true); ob_start(); ?><article class="bd-tool-card"><p class="bd-tool-kicker"><?php echo esc_html($get('brand')); ?></p><h2><?php echo esc_html(get_the_title($id)); ?></h2><p><?php echo esc_html($get('one_liner')); ?></p><?php if($get('problem')):?><p><strong>Resuelve:</strong> <?php echo esc_html($get('problem')); ?></p><?php endif;?><?php if($get('affiliate_url')):?><a rel="sponsored" href="<?php echo esc_url($get('affiliate_url')); ?>">Comprobar esta herramienta →</a><?php endif;?></article><?php return (string)ob_get_clean(); }
    public static function append_recommendation(string $content): string { if(!is_singular(self::TYPE)||!in_the_loop()||!is_main_query()||has_shortcode($content,'brujula_herramienta')) return $content; $id=get_the_ID(); $get=static fn(string $k)=>(string)get_post_meta($id,'_bd_'.$k,true); $url=$get('affiliate_url'); if(!$url)return $content; $cases=array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',$get('use_cases')))); $tool=sanitize_title($get('brand')?:get_the_title($id)); ob_start(); ?><section class="bd-recommendation" aria-labelledby="bd-recommendation-title"><p class="bd-tool-kicker">Recomendación de Brújula Digital</p><h2 id="bd-recommendation-title">Una forma sencilla de probar una solución concreta</h2><?php if($get('problem')):?><p><strong>El punto de dolor:</strong> <?php echo esc_html($get('problem')); ?></p><?php endif;?><?php if($cases):?><p><strong>Puede ayudarte a:</strong></p><ul><?php foreach(array_slice($cases,0,5) as $case):?><li><?php echo esc_html($case); ?></li><?php endforeach;?></ul><?php endif;?><p class="bd-commercial-disclosure">Aviso: esta página contiene un enlace de afiliación. Si contratas desde él, Brújula Digital podría recibir una comisión, sin coste adicional para ti.</p><p><a class="bd-cta" data-bd-affiliate-click="true" data-bd-tool="<?php echo esc_attr($tool); ?>" rel="sponsored noopener" href="<?php echo esc_url($url); ?>">Probar <?php echo esc_html($get('brand')?:'la herramienta'); ?> →</a></p></section><?php return $content.(string)ob_get_clean(); }
    public static function diagnostic_shortcode(): string { $categories=['productividad'=>'Ordena tu trabajo y recupera foco.','leads'=>'Centraliza consultas y evita perder seguimientos.','automatizacion'=>'Reduce tareas manuales entre herramientas.','marketing'=>'Crea materiales con más consistencia y menos esfuerzo.']; $pain=isset($_GET['dolor'])?sanitize_key(wp_unslash($_GET['dolor'])):''; $category=array_key_exists($pain,$categories)?$pain:''; $result=$category?add_query_arg('necesidad',$category,get_post_type_archive_link(self::TYPE)):''; ob_start(); ?><section class="bd-diagnostic" aria-labelledby="bd-diagnostic-title"><p class="bd-tool-kicker">Herramientas · acción · resultados</p><h1 id="bd-diagnostic-title">Encuentra el siguiente paso digital.</h1><p>Responde una pregunta y te orientaremos hacia herramientas relacionadas con tu problema.</p><form method="get" action="<?php echo esc_url(get_permalink()); ?>"><fieldset><legend>¿Qué te está haciendo perder más tiempo ahora?</legend><?php foreach($categories as $key=>$label):?><label><input type="radio" name="dolor" value="<?php echo esc_attr($key); ?>" <?php checked($category,$key); ?>> <span><?php echo esc_html($label); ?></span></label><?php endforeach;?></fieldset><button type="submit">Ver orientación</button></form><?php if($category&&$result):?><div class="bd-diagnostic-result" role="status"><p class="bd-tool-kicker">Resultado orientativo</p><h2><?php echo esc_html($categories[$category]); ?></h2><a href="<?php echo esc_url($result); ?>">Explorar herramientas verificadas</a><p class="bd-commercial-disclosure">Las recomendaciones son editoriales. La relación de afiliación se indicará claramente en cada ficha cuando corresponda.</p></div><?php endif;?></section><?php return (string)ob_get_clean(); }
    public static function conversion_tracking(): void {
        $landing_page = is_page(35);
        if(!is_singular(self::TYPE) && !$landing_page)return;
        ?><script>document.addEventListener('click',function(event){var link=event.target.closest('[data-bd-affiliate-click="true"],a[href*="aihomedesign.com"]');if(!link)return;var payload={event:'affiliate_click',tool:link.dataset.bdTool||'aihomedesign'};if(Array.isArray(window.dataLayer))window.dataLayer.push(payload);if(typeof window.gtag==='function')window.gtag('event','affiliate_click',{tool:payload.tool});});</script><?php
    }
    public static function styles(): void { if(!is_singular(self::TYPE)&&!is_page(17)&&!is_page(35))return; ?><style id="brujula-digital-catalog-styles">.page-id-35 .entry-title{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}.page-id-35 .entry-content{max-width:none!important;margin:0!important}.single-herramientas .entry-content,.page-id-17 .entry-content{max-width:780px;margin-inline:auto;font-size:1.08rem;line-height:1.7;color:#18345f}.single-herramientas .entry-title,.page-id-17 .entry-title{max-width:900px;margin:clamp(2rem,7vw,5rem) auto 2rem;color:#12355b;font-size:clamp(2.2rem,5vw,4.4rem);line-height:1.05;letter-spacing:-.04em}.single-herramientas .entry-content>p:first-child{font-size:1.28rem;color:#234e82}.page-id-17 .bd-home-lead{font-size:1.3rem;color:#234e82}.page-id-17 .bd-home-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin:1.5rem 0 4rem}.page-id-17 .bd-home-card{padding:1.5rem;border:1px solid #d8e8f5;border-radius:20px;background:linear-gradient(145deg,#fff,#f4fbff);box-shadow:0 12px 30px rgba(18,53,91,.08)}.page-id-17 .bd-home-card h3{margin:.2rem 0 .6rem;color:#12355b;font-size:1.35rem;line-height:1.2}.page-id-17 .bd-home-card p{margin:.4rem 0;color:#536b86}.page-id-17 .bd-home-number{color:#1267d6!important;font-weight:800;letter-spacing:.12em}.page-id-17 .bd-home-card a{display:inline-block;margin-top:.7rem;color:#1267d6;font-weight:800;text-decoration:underline;text-underline-offset:3px}.page-id-17 .bd-home-disclosure{margin-top:3rem;padding:1.5rem;border-radius:20px;background:#092b4c;color:#fff}.page-id-17 .bd-home-disclosure h2{color:#fff}.page-id-17 .bd-home-disclosure p{color:#d5e4f2}.bd-recommendation{margin:3rem 0;padding:clamp(1.5rem,4vw,2.5rem);border:1px solid #d8e8f5;border-radius:24px;background:linear-gradient(135deg,#f4fbff,#edf6ff);box-shadow:0 18px 45px rgba(18,53,91,.12)}.bd-tool-kicker{margin:0 0 .7rem;color:#1267d6;text-transform:uppercase;font-size:.76rem;font-weight:800;letter-spacing:.14em}.bd-recommendation h2{margin:.2rem 0 1rem;color:#12355b;font-size:clamp(1.55rem,3vw,2.2rem);line-height:1.15}.bd-recommendation ul{padding-left:1.3rem}.bd-commercial-disclosure{font-size:.88rem;line-height:1.5;color:#536b86}.bd-cta{display:inline-flex;align-items:center;justify-content:center;padding:.85rem 1.25rem;border-radius:999px;background:#1267d6;color:#fff!important;font-weight:800;text-decoration:none;box-shadow:0 10px 22px rgba(18,103,214,.25)}.bd-cta:hover,.bd-cta:focus{background:#0b4fa9;color:#fff!important}.bd-tool-card{padding:1.5rem;border:1px solid #d8e8f5;border-radius:20px;background:#f8fcff}@media(max-width:640px){.single-herramientas .entry-content,.page-id-17 .entry-content{font-size:1rem;padding-inline:1rem}.single-herramientas .entry-title,.page-id-17 .entry-title{padding-inline:1rem}.page-id-17 .bd-home-grid{grid-template-columns:1fr}.page-id-17 .bd-home-lead{font-size:1.08rem}.bd-recommendation{border-radius:18px;padding:1.25rem}.bd-cta{width:100%}}</style><?php if(is_page(35)): ?><script>(function(){function removeTitle(){var title=document.querySelector('.page-id-35 .entry-title');if(title)title.remove();}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',removeTitle);}else{removeTitle();}})();</script><?php endif; }
}
add_shortcode('brujula_diagnostico',[Brujula_Digital_Catalog::class,'diagnostic_shortcode']);
Brujula_Digital_Catalog::boot();
